import math
def alt(dec, lat, ha):
    d, l, h = map(math.radians, (dec, lat, ha))
    s = math.sin(d) * math.sin(l) + math.cos(d) * math.cos(l) * math.cos(h)
    return math.degrees(math.asin(s))
print(round(alt(38.78, 28.46, 0), 2), round(alt(38.78, 28.46, 180), 2))

