import math
def solve_kepler(M, e, tol=1e-12):
    E = M + e * math.sin(M)
    for n in range(1, 51):
        dE = (M - (E - e * math.sin(E))) / (1 - e * math.cos(E))
        E += dE
        if abs(dE) < tol:
            return round(E, 6), n
print(solve_kepler(1.0, 0.5))

C = 299_792_458.0
def relativistic_velocity(z):
    s = (1 + z) ** 2
    return C * (s - 1) / (s + 1)
z = 0.5
print(f"{C * z / 1000:.0f} {relativistic_velocity(z) / 1000:.0f}")
